          "status": "draft",
          "title": {
            "en": "Remembrance and fear",
            "pa": "ਸਿਮਰਨ ਅਤੇ ਡਰ"
          },
          "explanation": {
            "en": "The repeated construction prabh kai simaran(i) places each claim in relation to remembering God. Womb, death and death’s messenger belong to the bani’s teaching about birth, death and liberation; they should not be erased into a purely psychological reading. At the same time, the lines describe waking up inwardly rather than sleeping through life in fear. The ending connects this remembrance to holy company and love. These spiritual assurances should not be turned into promises of bodily invulnerability or used to judge a suffering person’s devotion.",
            "pa": "ਦੁਹਰਾਇਆ ਪ੍ਰਭ ਕੈ ਸਿਮਰਨਿ ਹਰ ਗੱਲ ਨੂੰ ਪ੍ਰਭੂ ਦੀ ਯਾਦ ਨਾਲ ਜੋੜਦਾ ਹੈ। ਗਰਭ, ਕਾਲ ਅਤੇ ਜਮ ਬਾਣੀ ਦੇ ਜਨਮ-ਮਰਨ ਅਤੇ ਮੁਕਤੀ ਦੇ ਧਾਰਮਿਕ ਸੰਦਰਭ ਵਿੱਚ ਹਨ; ਇਨ੍ਹਾਂ ਨੂੰ ਕੇਵਲ ਮਨੋਵਿਗਿਆਨਕ ਭਾਵ ਤੱਕ ਘਟਾਉਣਾ ਠੀਕ ਨਹੀਂ। ਨਾਲ ਹੀ ਪਉੜੀ ਡਰ ਵਿੱਚ ਸੁੱਤੇ ਰਹਿਣ ਦੀ ਥਾਂ ਅੰਦਰੋਂ ਜਾਗਣ ਬਾਰੇ ਦੱਸਦੀ ਹੈ। ਅੰਤ ਸਿਮਰਨ ਨੂੰ ਸਾਧ-ਸੰਗਤ ਅਤੇ ਪ੍ਰੇਮ ਨਾਲ ਜੋੜਦਾ ਹੈ। ਇਨ੍ਹਾਂ ਆਤਮਕ ਭਰੋਸਿਆਂ ਤੋਂ ਸਰੀਰ ਨੂੰ ਕਦੇ ਨੁਕਸਾਨ ਨਾ ਹੋਣ ਦੀ ਗਾਰੰਟੀ ਜਾਂ ਦੁਖੀ ਮਨੁੱਖ ਦੀ ਭਗਤੀ ਬਾਰੇ ਦੋਸ਼ ਨਹੀਂ ਬਣਾਉਣਾ ਚਾਹੀਦਾ।"
          },
