          "status": "draft",
          "title": {
            "en": "Redefining wealth and honour",
            "pa": "ਧਨ ਅਤੇ ਮਾਣ ਦੇ ਨਵੇਂ ਅਰਥ"
          },
          "explanation": {
            "en": "Those absorbed in remembrance are called wealthy, honourable, independent and royal. Read the accumulation of titles alongside the ending: the speaker asks only for the dust of their feet. This turns ordinary status inside out. Wealth is measured by Naam and freedom from inward neediness, rather than by property or dominance. “Imperishable” belongs to the spiritual account of life joined with the Divine, not to a claim that devotees’ bodies do not die. Grace, rather than self-appointment, brings a person to remembrance.",
            "pa": "ਸਿਮਰਨ ਵਾਲਿਆਂ ਨੂੰ ਧਨਵੰਤ, ਪਤਿਵੰਤ, ਬੇਮੁਹਤਾਜ ਅਤੇ ਰਾਜੇ ਕਿਹਾ ਹੈ। ਇਨ੍ਹਾਂ ਵਡਿਆਈਆਂ ਨੂੰ ਅੰਤ ਨਾਲ ਪੜ੍ਹੋ: ਬੋਲਣ ਵਾਲਾ ਉਨ੍ਹਾਂ ਦੇ ਚਰਨਾਂ ਦੀ ਧੂੜ ਹੀ ਮੰਗਦਾ ਹੈ। ਇਸ ਨਾਲ ਆਮ ਦੁਨਿਆਵੀ ਪਦਵੀ ਦਾ ਮਾਪ ਬਦਲਦਾ ਹੈ। ਧਨ ਦਾ ਮਤਲਬ ਨਾਮ ਅਤੇ ਅੰਦਰਲੀ ਮੁਥਾਜੀ ਤੋਂ ਛੁਟਕਾਰਾ ਹੈ, ਜਾਇਦਾਦ ਜਾਂ ਦਬਦਬਾ ਨਹੀਂ। ਅਬਿਨਾਸੀ ਨੂੰ ਪ੍ਰਭੂ ਨਾਲ ਜੁੜੇ ਆਤਮਕ ਜੀਵਨ ਦੇ ਸੰਦਰਭ ਵਿੱਚ ਪੜ੍ਹਨਾ ਹੈ; ਇਹ ਭਗਤ ਦੇ ਸਰੀਰ ਦੀ ਅਮਰਤਾ ਦਾ ਦਾਅਵਾ ਨਹੀਂ। ਸਿਮਰਨ ਨਾਲ ਜੋੜਨ ਵਾਲੀ ਸ਼ਕਤੀ ਕਿਰਪਾ ਹੈ, ਆਪਣੇ ਆਪ ਨੂੰ ਦਿੱਤਾ ਖ਼ਿਤਾਬ ਨਹੀਂ।"
          },
