          "status": "draft",
          "title": {
            "en": "Provisions, light and shade",
            "pa": "ਰਸਦ, ਚਾਨਣ ਅਤੇ ਛਾਂ"
          },
          "explanation": {
            "en": "Each pair of lines begins with a difficulty of travel and answers with a form of care. An immeasurable road receives provisions; darkness receives light; strangeness receives recognition; heat receives shade; thirst receives nectar-rain. These images express Naam’s sustaining companionship in the soul’s journey and can also illuminate present experiences of disorientation. The analogy should stay an analogy: the verses are not instructions to replace drinking water, physical shelter or care for a traveller with recitation.",
            "pa": "ਹਰ ਦੋ ਤੁਕਾਂ ਵਿੱਚ ਸਫ਼ਰ ਦੀ ਇੱਕ ਔਖ ਆਉਂਦੀ ਹੈ ਅਤੇ ਉਸ ਦਾ ਜਵਾਬ ਸੰਭਾਲ ਦੇ ਰੂਪ ਵਿੱਚ ਮਿਲਦਾ ਹੈ। ਬੇਹਿਸਾਬ ਰਸਤੇ ਲਈ ਰਸਦ, ਹਨੇਰੇ ਲਈ ਚਾਨਣ, ਅਣਜਾਣ ਥਾਂ ਲਈ ਜਾਣੂ, ਤਪਸ਼ ਲਈ ਛਾਂ ਅਤੇ ਪਿਆਸ ਲਈ ਅੰਮ੍ਰਿਤ ਦੀ ਵਰਖਾ ਹੈ। ਇਹ ਉਪਮਾਵਾਂ ਜੀਵ ਦੇ ਸਫ਼ਰ ਵਿੱਚ ਨਾਮ ਦਾ ਨਿਭਣ ਵਾਲਾ ਸਾਥ ਦੱਸਦੀਆਂ ਹਨ ਅਤੇ ਅੱਜ ਦੀ ਉਲਝਣ ਸਮਝਣ ਵਿੱਚ ਵੀ ਮਦਦ ਕਰ ਸਕਦੀਆਂ ਹਨ। ਉਪਮਾ ਨੂੰ ਉਪਮਾ ਹੀ ਰਹਿਣ ਦਿਓ: ਪਾਣੀ, ਸਰੀਰਕ ਪਨਾਹ ਜਾਂ ਯਾਤਰੀ ਦੀ ਦੇਖਭਾਲ ਦੀ ਥਾਂ ਸਿਰਫ਼ ਪਾਠ ਕਰਨ ਦੀ ਹਦਾਇਤ ਨਹੀਂ।"
          },
          "reflection": {
            "en": "Which image—provision, light, recognition, shade or rain—best names the support you need now?",
            "pa": "ਰਸਦ, ਚਾਨਣ, ਪਛਾਣ, ਛਾਂ ਜਾਂ ਵਰਖਾ ਵਿੱਚੋਂ ਕਿਹੜੀ ਉਪਮਾ ਇਸ ਵੇਲੇ ਤੁਹਾਨੂੰ ਲੋੜੀਂਦੇ ਆਸਰੇ ਨੂੰ ਚੰਗੀ ਤਰ੍ਹਾਂ ਦੱਸਦੀ ਹੈ?"
          },
