          "status": "draft",
          "title": {
            "en": "Appearance cannot quiet craving",
            "pa": "ਭੇਖ ਤ੍ਰਿਸ਼ਨਾ ਨਹੀਂ ਬੁਝਾਉਂਦਾ"
          },
          "explanation": {
            "en": "Cleverness, clothing, schemes and even an imagined escape to other realms cannot undo attachment while the net remains within. The pauri’s language of death’s reckoning keeps the religious seriousness of the problem. Yet the closing direction is sahaj subhaai: Naam spoken in steady, natural affection. This is not a contest in which strain proves sincerity. Read the critique of other acts alongside Pauri 8’s call for clean conduct; it challenges acts emptied of devotion, not ethical responsibility itself.",
            "pa": "ਚਤੁਰਾਈ, ਪਹਿਰਾਵਾ, ਉਪਾਵ ਅਤੇ ਹੋਰ ਲੋਕਾਂ ਵਿੱਚ ਚਲੇ ਜਾਣ ਦੀ ਕਲਪਨਾ ਵੀ ਮੋਹ ਨਹੀਂ ਖੋਲ੍ਹ ਸਕਦੀ ਜੇ ਜਾਲ ਅੰਦਰ ਕਾਇਮ ਹੈ। ਜਮ ਦੇ ਲੇਖੇ ਦੀ ਬੋਲੀ ਮੁੱਦੇ ਦੀ ਧਾਰਮਿਕ ਗੰਭੀਰਤਾ ਰੱਖਦੀ ਹੈ। ਫਿਰ ਵੀ ਅੰਤ ਦੀ ਦਿਸ਼ਾ ਸਹਜਿ ਸੁਭਾਇ ਹੈ: ਅਡੋਲ, ਕੁਦਰਤੀ ਪ੍ਰੇਮ ਨਾਲ ਨਾਮ ਉਚਾਰਨਾ। ਇਹ ਉਹ ਮੁਕਾਬਲਾ ਨਹੀਂ ਜਿਸ ਵਿੱਚ ਜ਼ੋਰ ਲਾਉਣਾ ਹੀ ਸੱਚਾਈ ਦਾ ਸਬੂਤ ਹੋਵੇ। ਹੋਰ ਕਰਮਾਂ ਦੀ ਆਲੋਚਨਾ ਅੱਠਵੀਂ ਪਉੜੀ ਦੀ ਸੁੱਚੀ ਕਰਣੀ ਨਾਲ ਪੜ੍ਹੋ; ਨਿਸ਼ਾਨਾ ਭਗਤੀ ਤੋਂ ਖਾਲੀ ਕਰਮ ਹਨ, ਨੈਤਿਕ ਜ਼ਿੰਮੇਵਾਰੀ ਨਹੀਂ।"
          },
