            "pa": "ਇਥੇ ਦਾਤਾਂ ਕੋਈ ਅਸਾਧਾਰਣ ਚਮਤਕਾਰ ਨਹੀਂ: ਪਰਿਵਾਰ ਨਾਲ ਹੱਸਣਾ, ਪਾਣੀ ਪੀਣਾ, ਹਵਾ, ਅੱਗ, ਰਸ ਅਤੇ ਸਰੀਰ ਦੇ ਅੰਗ ਹਨ। ਘਰ ਦੇ ਜੀਵਨ ਵਿੱਚ ਹੀ ਧਾਰਮਿਕ ਸੂਝ ਦਾ ਸਵਾਲ ਉੱਠਦਾ ਹੈ। ਕਮੀ ਦਾਤ ਵਰਤਣ ਵਿੱਚ ਨਹੀਂ, ਦਾਤਾਰ ਨੂੰ ਭੁੱਲਣ ਵਿੱਚ ਹੈ। “ਕਾਢਿ ਲੇਹੁ” ਨਾਲ ਅੰਤ ਦੋਸ਼ ਲਾਉਣ ਦੀ ਥਾਂ ਬੇਨਤੀ ਬਣਦਾ ਹੈ। ਸ਼ੁਕਰ ਅਤੇ ਜ਼ਿੰਮੇਵਾਰੀ ਇਕੱਠੇ ਰਹਿੰਦੇ ਹਨ।"
