            "en": "Jewel and shell, permanence and departure, sandalwood and ashes: the images expose a reversal of value. The mind labours for what cannot stay and postpones the certainty of death. The animal image depicts a stubborn habit of preference, not the worth of an actual animal or a poor person. The dark well names entrapment; the prayer asks for release. A useful application is to examine what is receiving disproportionate attention.",
            "pa": "ਰਤਨ-ਕਉਡੀ, ਟਿਕਾਅ-ਵਿਛੋੜਾ ਅਤੇ ਚੰਦਨ-ਸੁਆਹ ਦੇ ਬਿੰਬ ਮੁੱਲਾਂ ਦੀ ਉਲਟ ਦਿਖਾਉਂਦੇ ਹਨ। ਮਨ ਨਾਸਵੰਤ ਲਈ ਮਿਹਨਤ ਕਰਦਾ ਹੈ ਅਤੇ ਮੌਤ ਦੇ ਸੱਚ ਨੂੰ ਦੂਰ ਧੱਕਦਾ ਹੈ। ਖੋਤੇ ਦਾ ਰੂਪਕ ਆਦਤ ਦੀ ਜ਼ਿੱਦ ਦੱਸਦਾ ਹੈ; ਕਿਸੇ ਗਰੀਬ ਮਨੁੱਖ ਦੀ ਕੀਮਤ ਨਹੀਂ ਘਟਾਉਂਦਾ। ਹਨੇਰਾ ਖੂਹ ਮੋਹ ਦਾ ਫੰਧਾ ਹੈ। ਆਪਣੇ ਸਮੇਂ ਅਤੇ ਧਿਆਨ ਦੀ ਵੰਡ ਨੂੰ ਵੇਖਣਾ ਇਸ ਦੀ ਵਰਤੋਂ ਹੋ ਸਕਦੀ ਹੈ।"
