            "pa": "ਰੇਤ ਦਾ ਘਰ ਤਦ ਹੀ ਪੱਕਾ ਲੱਗਦਾ ਹੈ ਜਦੋਂ ਉਸ ਦੀ ਅਸਥਿਰਤਾ ਭੁੱਲ ਜਾਈਏ। ਮੌਤ ਨੂੰ ਵਿਸਾਰਨ ਦੇ ਨਾਲ ਵੈਰ, ਕਾਮ, ਕ੍ਰੋਧ, ਲੋਭ ਅਤੇ ਦਗ਼ਾ ਦੀ ਲੜੀ ਹੈ। “ਕਈ ਜਨਮ” ਜਨਮ-ਮਰਨ ਦੇ ਧਾਰਮਿਕ ਸੰਦਰਭ ਵਿੱਚ ਹੈ। ਆਪਣੇ ਇੱਕ ਜੀਵਨ ਵਿੱਚ ਦੁਹਰਾਉਂਦੀਆਂ ਆਦਤਾਂ ਵੇਖਣਾ ਇਸ ਦੀ ਵੱਖਰੀ ਵਰਤੋਂ ਹੋ ਸਕਦੀ ਹੈ, ਪਰ ਮੂਲ ਅਰਥ ਦਾ ਬਦਲ ਨਹੀਂ। ਅੰਤ ਫਿਰ ਮਿਹਰ ਦੀ ਬੇਨਤੀ ਹੈ।"
