            "pa": "ਆਵਾਜ਼, ਅਚਰਜ ਨਜ਼ਾਰੇ, ਬੋਲ, ਹੱਥਾਂ ਦੀ ਗਤੀ, ਕੰਮ ਦਾ ਫਲ ਅਤੇ ਸਹਜ ਇਕੋ ਲੜੀ ਵਿੱਚ ਹਨ। ਸਰੀਰ ਆਤਮਕ ਜੀਵਨ ਦਾ ਵੈਰੀ ਨਹੀਂ; ਇਸ ਦੀਆਂ ਸ਼ਕਤੀਆਂ ਜਾਗਰੂਕਤਾ ਦਾ ਮੌਕਾ ਬਣਦੀਆਂ ਹਨ। ਪੰਜਵੀਂ ਤੁਕ ਵਿੱਚ “ਹਸਤ” ਅਤੇ “ਕਰ” ਦੋਵੇਂ ਹੱਥਾਂ ਲਈ ਹਨ; ਅਰਥ ਕਰਦੇ ਸਮੇਂ ਇੱਕ ਨੂੰ ਪੈਰ ਨਹੀਂ ਬਣਾਇਆ ਗਿਆ। ਅੰਤ ਗੁਰੂ ਦੀ ਮਿਹਰ ਨਾਲ ਮਨ ਵਿੱਚ ਜਾਗਣ ਦਾ ਸੱਦਾ ਹੈ, ਕੋਈ ਅਲੌਕਿਕ ਨਜ਼ਾਰਾ ਲੱਭਣ ਦੀ ਮੰਗ ਨਹੀਂ।"
